import sys
import csv
from statistics import mean, median

def load(path):
    with open(path) as f:
        reader = csv.reader(f)
        header = next(reader)[1:]
        cols = {h: [] for h in header}
        for row in reader:
            for h, v in zip(header, row[1:]):
                cols[h].append(float(v))
    return cols

def drop_uncharacterized(cols):
    return {k: v for k, v in cols.items() if "uncharacterized" not in k}

def rank_top(cols, n):
    stats = [(k, mean(v)) for k, v in cols.items()]
    stats.sort(key=lambda x: x[1], reverse=True)
    return stats[:n]

def avg_cv(mean_cols, sd_cols):
    cvs = []
    for k in mean_cols:
        m = mean_cols[k]
        s = sd_cols[k]
        for mi, si in zip(m, s):
            if mi > 1e-9:
                cvs.append(si / mi)
    return median(cvs), mean(cvs)

if __name__ == "__main__":
    motif, mean_path, sd_path, kernel_top_names, out_path = sys.argv[1:6]
    mean_cols = drop_uncharacterized(load(mean_path))
    sd_cols = drop_uncharacterized(load(sd_path))

    med_cv, avg_cv_v = avg_cv(mean_cols, sd_cols)
    top_mc = rank_top(mean_cols, 15)

    kernel_names = set()
    with open(kernel_top_names) as f:
        for line in f:
            line = line.strip()
            if line:
                kernel_names.add(line.split("\t")[0])

    with open(out_path, "a") as out:
        out.write(f"\n=== {motif}: Monte Carlo robustness (n_graphs realizations per patient) ===\n")
        out.write(f"Median per-patient-per-feature CV (SD/mean) across random graph realizations: {med_cv:.3f}\n")
        out.write(f"Mean CV: {avg_cv_v:.3f}\n")
        out.write(f"\nTop 15 {motif} features by Monte Carlo mean (across patients, uncharacterized excluded):\n")
        mc_names = []
        for k, m in top_mc:
            # normalize feature name prefix (Dir_/W_/TT_/GSCC_) for cross-method comparability isn't needed; just report
            out.write(f"{k}\tMC_mean={m:.4f}\n")
            mc_names.append(k)
        # compare overlap with kernel-based top names (same prefix convention expected to differ: Dir_ vs kernel Dir_ etc.)
        overlap = [n for n in mc_names if n in kernel_names]
        out.write(f"\nOverlap with kernel-method top-15 list (same feature, regardless of rank): {len(overlap)}/15\n")
        if overlap:
            out.write("Overlapping features: " + ", ".join(overlap) + "\n")
    print("done", motif)

